INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('Agassiz Village Summer Camp', 'Agassiz Village', 'https://www.agassizvillage.org/summercamp', NULL, NULL, '781-860-0200', '71 Agassiz Village Road', 'Poland', 'ME', '04274', 'Maine', 'sleepaway', NULL, NULL, ARRAY['Swimming','Canoeing','Ropes course','Arts','Sports']::text[], NULL, 8, 17, NULL, NULL, 'Nonprofit overnight camp on Thompson Lake in Poland, Maine, for children from underserved communities. Campers ages 8-13 spend 11 days swimming, canoeing, on the ropes course, in arts and sports; teens 14-17 join the iThrive leadership program. Scholarships cover most of the cost, and transportation and meals are included.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, TRUE, NULL, NULL, '400+ acre campus with two miles of waterfront on Thompson Lake.', NULL, NULL, 2027, '600759b4-32ac-5f5e-81d8-b5097eed15b9', 'agassiz-village-summer-camp-poland', ST_GeogFromText('SRID=4326;POINT(-70.3936 44.0481)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.agassizvillage.org/summercamp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Alford Lake Camp', NULL, 'https://www.alfordlakecamp.com', 'https://alfordlake.campintouch.com/ui/forms/application/camper/App', 'explore@alfordlakecamp.com', '207-785-2400', '258 Alford Lake Road', 'Hope', 'ME', '04847', 'Maine', 'sleepaway', ARRAY['sports','performing_arts']::text[], NULL, ARRAY['Drama','Tennis','Canoeing','Sailing','Riding','Library','Out of Camp Trips']::text[], 'girls', 8, 17, NULL, NULL, 'Residential summer camp for girls on Alford Lake in Hope, Maine, offering a 7-week full season or two 3.5-week sessions. Campers choose the activities they focus on, and tuition covers out-of-camp trips and riding.', NULL, NULL, 10350, 15800, NULL, NULL, NULL, NULL, NULL, TRUE, 'A $1,500 tuition deposit is due at registration. It is non-refundable and is credited toward tuition. Credit card convenience fees (3.5%) are also non-refundable. The page does not give a refund policy for the rest of the tuition.', NULL, NULL, NULL, NULL, 2027, '952d5d8f-1b62-51ee-8953-366a0a5f808c', 'alford-lake-camp-hope', ST_GeogFromText('SRID=4326;POINT(-69.1885 44.2412)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.alfordlakecamp.com','https://www.alfordlakecamp.com/rates-dates']::text[], '2026-11-13', '2026-11-13', TRUE),
('Birch Rock Camp', NULL, 'https://birchrock.org/', NULL, NULL, '207-583-4478', '293 McWain Hill Rd', 'Waterford', 'ME', '04088', 'Maine', 'sleepaway', ARRAY['nature','sports']::text[], NULL, ARRAY['Soccer clinic','Junior Maine Guides','Maine Wilderness Adventure','Outing Club','Academic tutoring (extra charge)']::text[], 'boys', 7, NULL, NULL, NULL, 'Overnight summer camp for boys in Waterford, Maine, offering full, half and two-week sessions. It also has a Cubs program for new campers ages 7-12 and a leadership program for ages 16-17.', NULL, NULL, 5500, 13000, NULL, NULL, NULL, NULL, NULL, TRUE, 'Cancellations received in writing before April 1 can roll over to the next season or be refunded, minus the $1,500 non-refundable registration deposit. There is no tuition reduction for late arrival or early departure, and no refund if a camper is sent home for conduct. Half of tuition is due February 1 and the rest May 1. Credit card payments carry a 3.5% fee.', NULL, NULL, TRUE, 'https://birchrock.org/', 2027, '44213f87-a244-579d-810f-cc4a4ec47484', 'birch-rock-camp-waterford', ST_GeogFromText('SRID=4326;POINT(-70.7223 44.2028)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://birchrock.org/','https://birchrock.org/dates-rates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Bridgton Sports Camp', NULL, 'https://www.bridgtonsportscamp.com/', 'https://www.bridgtonsportscamp.com/enroll', NULL, '866-283-5943', '11 Academy Lane', 'North Bridgton', 'ME', '04057', 'Maine', 'sleepaway', ARRAY['sports']::text[], NULL, ARRAY['Athletics','Waterfront activities','Hockey (additional fee)','Out-of-camp trips','Rafting trip (oldest campers, additional fee)']::text[], 'boys', 8, 15, NULL, NULL, 'Overnight sports camp for boys ages 8-15 in North Bridgton, Maine, with two three-week sessions in 2027 focused on athletics and waterfront activities. Tuition is all-inclusive: dorm lodging, meals, laundry, trips and canteen.', NULL, NULL, 6500, 6500, NULL, 'session', NULL, TRUE, TRUE, NULL, NULL, NULL, 'The page mentions waterfront activities. It does not describe the waterfront or the swim program.', NULL, NULL, 2027, '1ec654cd-b596-5db9-8bcb-8c577cec060c', 'bridgton-sports-camp-north-bridgton', ST_GeogFromText('SRID=4326;POINT(-70.7433 44.0475)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.bridgtonsportscamp.com/dates-rates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Agawam', NULL, 'https://campagawam.org/', 'https://campagawam.campintouch.com/ui/forms/application/camper/App', NULL, '(207) 627-4780', '54 Agawam Road', 'Raymond', 'ME', '04071', 'Maine', 'sleepaway', ARRAY['nature','sports']::text[], NULL, ARRAY['Trips to Acadia, Allagash (canoe), Rangeley Lakes, Mt. Katahdin, Mt. Washington and Moosehead','Lifeguard certification (Senior Club)','Wilderness first aid certification (Senior Club)']::text[], 'boys', 8, 15, NULL, NULL, 'An overnight summer camp for boys in Raymond, Maine, with 7-week and 3.5-week sessions and a Senior Club leadership program for former campers. Tuition covers meals, weekly laundry and most activities.', NULL, NULL, 8500, 13550, NULL, NULL, NULL, TRUE, TRUE, NULL, '$2,000 deposit is non-refundable if enrollment is cancelled after January 1. If a camper leaves during the summer by mutual agreement with the director for health or adjustment reasons, tuition is refunded pro rata. No refund if he leaves by his own choice or for breaking camp rules. Unspent money in the $300 personal account is refunded.', NULL, '165-acre campus on Crescent Lake in Raymond.', NULL, NULL, 2027, '62575419-1e39-5326-b242-4f9dddcca94e', 'camp-agawam-raymond', ST_GeogFromText('SRID=4326;POINT(-70.4685 43.9176)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://campagawam.org/','https://campagawam.org/enrollment-and-pricing/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Androscoggin', NULL, 'https://www.campandro.com/', NULL, 'directors@campandro.com', '(207) 685-4441', '126 Leadbetter Road', 'Wayne', 'ME', '04284', 'Maine', 'sleepaway', NULL, NULL, ARRAY['Tennis','Baseball','Basketball','Soccer','Lacrosse','Golf','Archery','Riflery','Ropes course','Climbing wall','Mountain biking','Crafts','Pottery','Woodworking','Video and photography','Music','Drama','Swimming','Sailing','Waterskiing and wakeboarding','Canoeing and kayaking','Windsurfing','Fishing']::text[], 'boys', NULL, 15, NULL, NULL, 'Overnight camp for boys on Lake Androscoggin in Wayne, Maine, founded in 1907. For 2027 it offers a seven-week full session or a four-week session at the start of the summer, with all-inclusive tuition.', NULL, NULL, 12000, 18300, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Nearly 2,000 feet of beachfront on Lake Androscoggin with a 200-foot dock for swim instruction, sail and fishing docks, and certified lifeguards.', NULL, NULL, 2027, '48a7c072-9f08-5c00-96f1-0bbc4fd90588', 'camp-androscoggin', ST_GeogFromText('SRID=4326;POINT(-70.068 44.3415)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.campandro.com/','https://www.campandro.com/contact-us/','https://www.campandro.com/for-parents/dates-rates/','https://www.campandro.com/the-camp-brochure/','https://www.campandro.com/the-camp-brochure/activities-facilities/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Arcadia', NULL, 'https://www.camparcadia.com', 'https://arcadia.campintouch.com/ui/forms/application/camper/App', 'Louise.Johnson@camparcadia.com', '207-627-4605', '1 Arcadia Lane', 'Otisfield', 'ME', '04270', 'Maine', 'sleepaway', NULL, NULL, NULL, 'girls', 7, 17, 1, 11, 'Camp Arcadia is an overnight summer camp for girls in Otisfield, Maine, running since 1916. For 2027 it offers a full season, two main sessions, and shorter introductory sessions for girls in grades 1-3.', NULL, NULL, 5500, 12600, NULL, NULL, NULL, NULL, NULL, TRUE, 'The $1,500 deposit is non-refundable and counts toward tuition. If you cancel in writing before March 15, 2027, the tuition can be rolled over to 2028 or refunded, minus the deposit. There is no reduction for late arrival, early departure or withdrawal, or for a camper sent home for behavior.', NULL, NULL, TRUE, 'https://www.camparcadia.com/aca-accredited', 2027, '5578458a-943a-5d2f-9775-b8bb0efb8400', 'camp-arcadia-otisfield', ST_GeogFromText('SRID=4326;POINT(-70.5494 44.0906)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.camparcadia.com/','https://www.camparcadia.com/aca-accredited','https://www.camparcadia.com/dates-rates']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Beech Cliff', 'Camp Beech Cliff', 'https://www.campbeechcliff.org', 'https://campbeechcliff.campbrainregistration.com', 'info@campbeechcliff.org', '(207) 244-0365', '264 Beech Hill Rd', 'Mount Desert', 'ME', '04660', 'Maine', 'day', NULL, NULL, NULL, NULL, NULL, NULL, 0, 7, 'Weekly day camp on Mount Desert Island, Maine. Traditional camps are grouped by grade for K-7, with separate specialty, teen and Friday overnight programs. Rates are lower for Hancock County residents.', NULL, NULL, 300, 495, 495, 'week', NULL, NULL, NULL, TRUE, 'Each camper pays a $30 registration fee once per season. It is non-refundable unless the camper stays on the waitlist and never gets a spot. A $50 deposit per week ($25 for approved campership applicants) is due by May 1 and is non-refundable after May 1. The weekly balance is due, and can be refunded, up to two weeks before the camp week starts; after that no refunds are given. There are no discounts if a camper attends only part of a week.', NULL, 'Traditional campers go to the waterfront every day for swimming, weather permitting. The page gives no details on swim instruction or supervision.', NULL, NULL, 2026, 'f5413d7b-941f-5235-9082-b2de2b0f4c04', 'camp-beech-cliff-mount-desert', ST_GeogFromText('SRID=4326;POINT(-68.3304 44.3336)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.campbeechcliff.org/dates-rates','https://www.campbeechcliff.org/traditional-k7']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp CaPella – Weekly Overnight Camp', NULL, 'https://campcapella.org/weekly-overnight-camp', NULL, NULL, '(207) 843-5104', '8 Pearl Point Road', 'Dedham', 'ME', '04429', 'Maine', 'sleepaway', ARRAY['special_needs']::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A small lakefront camp in Dedham, Maine for people with disabilities. In the weekly overnight program campers arrive Sunday afternoon and stay until Friday, each week is for one age group, and overnight campers join the day campers for traditional camp activities.', NULL, NULL, NULL, NULL, 2000, 'week', NULL, NULL, TRUE, TRUE, NULL, 'Each week welcomes campers of all abilities and the camp stresses inclusion. Special diets will be accommodated where possible, and families may send their own food. Applicants must meet the eligibility policy in the application. Contact the office if you''re unsure whether the camp is a good fit.', NULL, NULL, NULL, 2026, '4f7f96da-15b7-5be3-a2d9-c9cb0841ec11', 'camp-capella-weekly-overnight-camp-dedham', ST_GeogFromText('SRID=4326;POINT(-68.558 44.7009)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://campcapella.org/','https://campcapella.org/weekly-overnight-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Caribou', NULL, 'https://www.campcaribou.com/', 'https://caribou.campintouch.com/ui/forms/application/camper/App', NULL, '207.872.9313', '1 Caribou Way', 'Winslow', 'ME', '04901', 'Maine', 'sleepaway', ARRAY['sports','arts']::text[], NULL, ARRAY['Basketball','Soccer','Baseball','Tennis','Football','Hockey','Volleyball','Swimming','Sailing','Water skiing','Kayaking','Canoeing','Woodworking','Culinary arts','Painting','Drawing','Photography','Hiking','Camping','Fishing','Archery']::text[], 'boys', NULL, NULL, NULL, NULL, 'Overnight summer camp for boys on a lake in Winslow, Maine. For 2027 families can book the full season or one of two sessions of about three and a half weeks, with land and water sports, creative arts and outdoor adventure.', NULL, NULL, 10950, 17700, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, 'c6e01aba-d5a3-5140-aee2-60d8a4e6fd15', 'camp-caribou-winslow', ST_GeogFromText('SRID=4326;POINT(-69.5772 44.5239)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.campcaribou.com/future-families/dates-rates/','https://www.campcaribou.com/future-families/faqs/','https://www.campcaribou.com/future-families/our-program/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Cedar', NULL, 'https://campcedar.com', 'https://cedar.campintouch.com/ui/forms/application/camper/App', 'info@campcedar.com', '(207) 627-4266', '112 Camp Cedar Road', 'Casco', 'ME', '04015', 'Maine', 'sleepaway', NULL, NULL, ARRAY['Basketball','Baseball','Soccer','Hockey','Lacrosse','Tennis','Volleyball','Swimming','Biking','Sailing','Water skiing','Golf','Hiking','Nature','Trips','Zip line','Ropes course','Creative arts']::text[], 'boys', 8, 15, NULL, NULL, 'Overnight summer camp for boys ages 8 to 15 on Coffee Pond in Casco, Maine. For 2027 it offers a seven-week full session (June 27 to August 13); a limited number of first-time campers can come for 4 or 5 weeks.', NULL, NULL, 12700, 18100, NULL, NULL, NULL, TRUE, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, 2027, 'd895d4a7-5469-5886-b41b-0b7b31038caa', 'camp-cedar-casco', ST_GeogFromText('SRID=4326;POINT(-70.5132 43.952)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://campcedar.com/dates-rates-41/','https://campcedar.com/faq/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Cobbossee', NULL, 'https://www.campcobbossee.com/', 'https://cobbossee.campintouch.com/ui/forms/application/camper/App', NULL, '1-207-933-4503', '1 Camp Cobbossee Circle', 'Monmouth', 'ME', '04259', 'Maine', 'sleepaway', ARRAY['sports']::text[], NULL, ARRAY['Land sports','Water sports','Hobbies','Baseball','Inter-camp competitions','Adventure']::text[], 'boys', NULL, NULL, NULL, NULL, 'Overnight sports and adventure camp for boys in Monmouth, Maine, running since 1902. Campers stay for sessions of about three and a half weeks, and first-time campers in younger grades can choose a two-week option.', NULL, NULL, 6975, 10150, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '3a6029f2-b7d0-5427-8495-8b6b642253db', 'camp-cobbossee-monmouth', ST_GeogFromText('SRID=4326;POINT(-70.0147 44.2335)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.campcobbossee.com/need-know/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Fernwood', NULL, 'https://www.campfernwood.com/', 'https://fernwood.campintouch.com/ui/forms/application/camper/App', 'fernwood@campfernwood.com', '207-998-4346', '48 Camp Fernwood Lane', 'Poland', 'ME', '04274', 'Maine', 'sleepaway', NULL, NULL, ARRAY['Horseback riding (optional, extra cost)','Tennis (private lessons optional, extra cost)','Tripping']::text[], 'girls', 8, 15, NULL, NULL, 'An overnight summer camp for girls ages 8 to 15 on Lake Thompson in Poland, Maine, running since 1921. It runs one full session of about seven weeks.', NULL, NULL, 17300, 17300, NULL, NULL, NULL, TRUE, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '3d67cb99-73c0-527e-8bb9-fb0406c40dce', 'camp-fernwood', ST_GeogFromText('SRID=4326;POINT(-70.3936 44.0481)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.campfernwood.com/contact-us/','https://www.campfernwood.com/dates-and-pricing/','https://www.campfernwood.com/general-information/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Kawanhee', NULL, 'https://www.kawanhee.com', 'https://campkawanhee.campfront.com/parent/register', 'kawanhee@kawanhee.com', '(207) 585-2210', '58 Kawanhee Lane', 'Weld', 'ME', '04285', 'Maine', 'sleepaway', ARRAY['sports','nature']::text[], NULL, ARRAY['Swimming and lifeguard training','Water skiing','Sailing','Canoeing','Kayaking','Tennis','Archery','Riflery','Woodworking','Hiking and mountain trips','River trips','Fishing','Saturday team competitions']::text[], 'boys', 7, 17, NULL, NULL, 'An overnight camp for boys on a lake in Weld, Maine. Boys live in lodges of 8 to 10 campers with two counselors, and stays run from 2 weeks up to a 7-week full season. Boys aged 16 and 17 can join a Leadership Training program.', NULL, NULL, 5500, 11500, NULL, NULL, NULL, TRUE, TRUE, NULL, NULL, 'The kitchen works with families to provide gluten-free and allergy-friendly meals, and vegetarian options are always available. A Maine-licensed RN works full-time on site and lives in the infirmary. All medications, including over-the-counter ones, are kept in the infirmary and given at mealtimes unless a prescription requires a different time. Counselors handle bedwetting privately.', 'Camp is on Webb Lake. The swimming area in the camp cove has a sandy beach, docks, a floating safety line and several lifeguard stations. Campers can join an optional 7 AM ''Polar Bear'' swim. Waterfront staff get extra training before the season.', NULL, NULL, 2027, '09b8e31f-560a-5b30-9e8b-9b89d5361496', 'camp-kawanhee-weld', ST_GeogFromText('SRID=4326;POINT(-70.4493 44.6875)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://www.kawanhee.com/parents/','https://www.kawanhee.com/the-experience/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp KV', 'Kennebec Valley YMCA', 'https://kvymca.org/camp-programs', 'https://campkv.campbrainregistration.com/', 'jennifer@kvymca.org', '207-685-4644', '916 Main Street', 'Readfield', 'ME', '04355', 'Maine', 'day', ARRAY['sports','nature','arts']::text[], NULL, ARRAY['Swimming','Boating','Arts & Crafts','Nature Hikes and Activities','Archery','Field Sports','Disc Golf','Literacy']::text[], 'coed', 5, 14, 0, 8, 'State-licensed co-ed day camp run by the Kennebec Valley YMCA on Maranacook Lake in Readfield, Maine, for ages 5 to 14. Camp is booked one week at a time, with swimming, boating, archery, arts and crafts, nature, field sports and disc golf.', NULL, NULL, 208, 780, 260, 'week', NULL, NULL, NULL, TRUE, 'Each week you register for needs a $50 non-refundable deposit. You then pay in full at registration, in full before camp starts, or weekly.', NULL, 'Camp is on Maranacook Lake, with swimming and boating. A 2-week Lifeguard/Leader in Training program for ages 12 to 14 teaches CPR, water scanning and shallow water rescues. The pages don''t describe swim tests or waterfront supervision.', NULL, NULL, 2026, '2cd9aedc-31a3-5626-9e26-9c3c7e081f0f', 'camp-kv-readfield', ST_GeogFromText('SRID=4326;POINT(-69.9502 44.3844)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://kvymca.org/camp-programs','https://kvymca.org/files/2026/06/Camp_KV_Brochure_26-2_(5).pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Laughing Loon', NULL, 'https://www.camplaughingloon.com/', 'https://campscui.active.com/orgs/CampLaughingLoon?orglink=camps-registration', 'info@camplaughingloon.com', '207-247-6329', '52 Laughing Loon Lane', 'East Waterboro', 'ME', '04030', 'Maine', 'day', ARRAY['sports','arts','nature','performing_arts']::text[], NULL, ARRAY['swimming lessons','canoeing','archery','sports and games','nature','drama','arts and crafts','camp sing']::text[], NULL, 6, 12, NULL, NULL, 'A non-profit summer day camp for ages 6 to 12 on Little Ossipee Lake in East Waterboro, Maine, running since 1917. Campers rotate through swimming lessons, canoeing, archery, arts and crafts, sports and nature or drama, with before and after care.', NULL, NULL, NULL, NULL, 310, 'week', TRUE, FALSE, FALSE, TRUE, 'A $50 non-refundable deposit per week holds the spot, with the balance due May 31, 2027. Cancel at least 10 days before a week for a refund minus the deposit; within 10 days, tuition is not refunded.', NULL, 'Camp sits on Little Ossipee Lake, with water on three sides. Campers have daily swimming and canoeing lessons from certified instructors, plus free swim in the afternoon.', NULL, NULL, 2027, '19a07b67-68fc-5c92-ab24-7e1b985d274a', 'camp-laughing-loon-east-waterboro', ST_GeogFromText('SRID=4326;POINT(-70.7301 43.6038)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.camplaughingloon.com/','https://www.camplaughingloon.com/a-typical-day-at-cll','https://www.camplaughingloon.com/camperships-financial-aid','https://www.camplaughingloon.com/copy-of-registration','https://www.camplaughingloon.com/directions','https://www.camplaughingloon.com/extended-day-program','https://www.camplaughingloon.com/payment']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Laurel', NULL, 'https://www.camplaurel.com', 'https://www.camplaurel.com/enroll/', 'summer@camplaurel.com', '203-227-8866', NULL, 'Readfield', 'ME', '04355', 'Maine', 'sleepaway', ARRAY['sports','arts','nature']::text[], NULL, ARRAY['Boys'' Athletics','Girls'' Athletics','Waterfront','Tennis','Adventure','Inter-Arts','Equestrian']::text[], 'coed', NULL, NULL, 2, 11, 'Co-ed overnight camp on Echo Lake in Readfield, Maine, with one seven-week season (June 26 to August 11, 2027). Boys and girls live in separate campuses and choose from athletics, tennis, waterfront sports, adventure, arts and optional riding.', NULL, NULL, 18500, 18500, NULL, 'session', NULL, TRUE, TRUE, NULL, NULL, NULL, 'Camp fronts on spring-fed Echo Lake. Swimming uses American Red Cross instruction, and the waterfront offers waterskiing, wakeboarding, sailing, paddleboarding, canoeing, kayaking, snorkeling and a swim team.', NULL, NULL, 2027, '2440b811-bf74-572f-90f2-0d47a50fc375', 'camp-laurel-readfield', ST_GeogFromText('SRID=4326;POINT(-69.9502 44.3844)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.camplaurel.com/about-camp-laurel/first-time-campers/','https://www.camplaurel.com/about-camp-laurel/frequently-asked-questions/','https://www.camplaurel.com/about-camp-laurel/summer-camp-program/waterfront/','https://www.camplaurel.com/summer-camp-families/dates-fees/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Manitou', NULL, 'https://campmanitou.com/', 'https://manitou.campintouch.com/ui/forms/application/camper/App', 'mailbox@campmanitou.com', '(207) 465-2271', '47 Camp Manitou Cove', 'Oakland', 'ME', '04963', 'Maine', 'sleepaway', ARRAY['sports','arts','performing_arts']::text[], NULL, ARRAY['baseball','basketball','soccer','lacrosse','tennis','golf','roller hockey','archery','BMX','climbing tower','ropes course','swimming','sailing','water-skiing','wakeboarding','canoeing and kayaking','fishing','theater','ceramics','computer animation','radio','culinary']::text[], 'boys', 7, 16, NULL, NULL, 'Overnight camp for boys ages 7 to 16 on East Pond in the Belgrade Lakes region, with an address in Oakland, Maine. Boys plan their own schedules across land sports, water sports and creative arts such as theater, radio and animation, in 3-week half sessions or a 7-week full session.', NULL, NULL, 10950, 18350, NULL, 'session', NULL, TRUE, TRUE, NULL, NULL, NULL, 'Camp is on East Pond. Sixteen instructional water activities include swimming, competitive swimming, sailing, water-skiing, wakeboarding, canoeing, kayaking and fishing. CPR, basic rescue and advanced lifesaving courses are offered.', NULL, NULL, 2027, 'f3b7740b-e756-5694-ab89-436911b489f6', 'camp-manitou', ST_GeogFromText('SRID=4326;POINT(-69.7332 44.5793)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://campmanitou.com/','https://campmanitou.com/collections/activities/watersports','https://campmanitou.com/contact','https://campmanitou.com/current-families/travel-to-camp','https://campmanitou.com/prospective-families/activities','https://campmanitou.com/prospective-families/camp-food','https://campmanitou.com/sessions']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Matoaka', NULL, 'https://www.matoaka.com/', 'https://matoaka.campintouch.com/v2/camper/application/app0.aspx', NULL, '207-512-2300', 'One Great Place', 'Smithfield', 'ME', '04978', 'Maine', 'sleepaway', ARRAY['sports','arts','performing_arts']::text[], NULL, ARRAY['tennis','swimming','gymnastics','horseback riding (English, extra fee)','archery','basketball','lacrosse','golf','mountain biking','dance','theater','ceramics','creative arts','sewing','culinary arts','fishing','ropes course','ninja warrior course','yoga','fitness']::text[], 'girls', NULL, NULL, NULL, NULL, 'Overnight camp for girls on East Pond in Smithfield, Maine, open since 1951. Girls choose from over 30 activities, including tennis, gymnastics, swimming, dance, theater, arts and riding, in two 3.5-week half sessions or one 7-week full session.', NULL, NULL, 11100, 18650, NULL, 'session', NULL, TRUE, TRUE, NULL, 'A fully refundable $3,000 deposit is due with the online application. The page doesn''t give a refund policy for the rest of the tuition. Card payments after the deposit carry a 3% fee.', 'A Food Allergy Coach and five nurses support campers with food allergies, dietary restrictions and medical needs. The site doesn''t describe support for other special needs.', 'Two swim areas: a 10,000 square-foot area on East Pond with three enclosed cribs and an aqua park, and a heated 25-meter pool with waterslides. Swim staff are lifeguards and certified instructors teaching the Red Cross curriculum; younger campers take three swim lessons a week.', TRUE, 'https://www.matoaka.com/faq/', 2027, 'b8cac632-9feb-544f-afcb-77ac07b1cd9f', 'camp-matoaka-smithfield', ST_GeogFromText('SRID=4326;POINT(-69.7999 44.6418)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.matoaka.com/','https://www.matoaka.com/activities/','https://www.matoaka.com/faq/','https://www.matoaka.com/nutrition-wellness/','https://www.matoaka.com/rates-and-dates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Med-O-Lark', NULL, 'https://www.medolark.com', 'https://medolark.campintouch.com/ui/forms/application/camper/App', 'welcome@medolark.com', '207-220-3530', '82 Medolark Rd', 'Washington', 'ME', '04574', 'Maine', 'sleepaway', ARRAY['arts','performing_arts']::text[], NULL, ARRAY['ceramics','hot glass','stained glass','blacksmithing','fashion design','candle making','woodworking','painting','drama and plays','ballet','hip hop','guitar and drum lessons','cabaret','waterfront']::text[], NULL, 7, NULL, NULL, NULL, 'Overnight creative arts camp in Washington, Maine, where campers pick their own activities, from hot glass and fashion design to theater, dance and music. Sessions run 2, 4, 6 or 8 weeks from June 27 to August 21, 2027; 4-week campers can join the musical.', NULL, NULL, 5200, 14800, NULL, 'session', NULL, NULL, TRUE, NULL, 'Deposits are fully refundable if you change or cancel by March 1, 2027, and tuition paid in full is refundable until then. Half the remaining tuition is due March 1 and the rest May 1. Credit cards carry a 3% fee.', NULL, 'Camp is on a lake in Washington, Maine, and tuition includes the waterfront. The pages give no details about swim tests or supervision.', NULL, NULL, 2027, 'ef1eb35c-fd2f-5f42-8924-ab8f42279939', 'camp-med-o-lark-washington', ST_GeogFromText('SRID=4326;POINT(-69.3915 44.2606)'), FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.medolark.com/','https://www.medolark.com/2027','https://www.medolark.com/activities','https://www.medolark.com/camp-life']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp North Star', NULL, 'https://campnorthstarmaine.com/', 'https://campnorthstarmaine.com/enrollment-application/', 'info@cnsmaine.com', '201.414.6322', '200 Verrill Road', 'Poland Spring', 'ME', '04274', 'Maine', 'sleepaway', ARRAY['sports','arts','outdoor']::text[], NULL, ARRAY['arts','athletics','outdoor adventure and ropes course','swimming','sailing','equestrian (extra fee)','golf (extra fee)']::text[], 'coed', NULL, NULL, 2, 11, 'Co-ed overnight camp on Worthley Pond in Poland Spring, Maine, for rising 2nd to 11th graders. Mornings are scheduled activity periods and afternoons are electives across arts, athletics, outdoor and waterfront, in sessions of 2 to 7 weeks between June 27 and August 14, 2027.', NULL, NULL, 5045, 14750, NULL, 'session', NULL, NULL, NULL, NULL, 'All fees, including the deposit, are fully refundable through January 1, 2027, and not refundable after that. The balance is paid in monthly installments ending June 1, or in full at registration.', NULL, 'Camp is on the shore of Worthley Pond, with swimming, sailing and other lake activities. The pages don''t describe swim tests or supervision.', NULL, NULL, 2027, '7047027a-62fe-5666-90e3-87f7dba0ff54', 'camp-north-star-poland-spring', ST_GeogFromText('SRID=4326;POINT(-70.3936 44.0481)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://campnorthstarmaine.com/','https://campnorthstarmaine.com/activities/','https://campnorthstarmaine.com/dates-rates/','https://campnorthstarmaine.com/our-story/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Takajo', NULL, 'https://www.camptakajo.com/', NULL, 'info@camptakajo.com', '(207) 693-6675', '60 Takajo Road', 'Naples', 'ME', '04055', 'Maine', 'sleepaway', ARRAY['sports']::text[], NULL, ARRAY['Sports','Waterfront','Hobbies','Skills','Pioneering']::text[], 'boys', NULL, NULL, NULL, NULL, 'Camp Takajo is a full-season overnight camp for boys in Naples, Maine, founded in 1947. The 2027 season runs about seven weeks, with sports, waterfront, hobbies, skills and pioneering.', NULL, NULL, 18200, 18200, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '23a685b1-4c51-5c4e-b495-0f1d6eea4856', 'camp-takajo', ST_GeogFromText('SRID=4326;POINT(-70.6393 43.9758)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.camptakajo.com/','https://www.camptakajo.com/about/','https://www.camptakajo.com/about/dates-tuition/','https://www.camptakajo.com/contact/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Tapawingo', 'Camp Tapawingo', 'https://www.camptapawingo.com', 'https://camptapawingo.campintouch.com/ui/forms/application/camper/App', 'Marianne@camptapawingo.com', '207-647-3351', '166 Tapawingo Road', 'Sweden', 'ME', '04040', 'Maine', 'sleepaway', NULL, NULL, ARRAY['Arts & crafts','Landsports (basketball, soccer, softball, volleyball, field hockey, lacrosse)','Archery and gymnastics','Tennis and pickleball','Horseback riding (optional, extra fee)','Performing arts','Trips (camping, hiking, backpacking, canoeing)','Ropes course','Waterfront (sailing, paddleboarding, canoeing, water skiing, tubing, swimming)']::text[], 'girls', NULL, NULL, NULL, NULL, 'Camp Tapawingo is a girls'' overnight camp in Sweden, Maine. For 2027 it offers a seven-week full summer, two shorter sessions and a CIT program.', NULL, NULL, 9100, 16050, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The camp is on Keyes Pond, a 191-acre spring-fed pond, and is the only operator of motorized watercraft on it. All campers swim at least five days a week.', NULL, NULL, 2027, 'e343ea5e-dc2c-546c-8ba9-132cd6389feb', 'camp-tapawingo-sweden', ST_GeogFromText('SRID=4326;POINT(-70.8055 44.1231)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.camptapawingo.com/dates-rates','https://www.camptapawingo.com/explore/activities','https://www.camptapawingo.com/explore/faqs']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Timanous', 'Camp Timanous', 'https://www.timanous.org/', 'https://timanous.campintouch.com/ui/forms/application/camper/App', NULL, '207-655-4569', '85 Plains Road', 'Raymond', 'ME', '04071', 'Maine', 'sleepaway', ARRAY['sports','arts','nature']::text[], NULL, ARRAY['Archery','Basketball','Baseball','Canoeing','Disc golf','Drama','Fishing','Handicrafts','Kayaking','Lacrosse','Music','Nature','Paddleboarding','Ping pong','Pickleball','Riflery','Running','Sailing','Soccer','Softball','Swimming','Tennis','Ultimate frisbee','Volleyball','Waterskiing','Wakeboarding','Woodshop','Camping trips']::text[], 'boys', NULL, NULL, NULL, NULL, 'Boys'' summer camp in Raymond, Maine, with a seven-week full season or two half sessions. Tuition covers activities such as woodshop, crafts, waterskiing and camping trips, plus laundry, health insurance and the yearbook.', NULL, NULL, 8900, 13400, NULL, NULL, NULL, NULL, NULL, TRUE, 'Full refund of all money paid, minus a $200 administrative fee, through March 1. After that, refunds are made only if another camper fills the spot. Tuition insurance (Program Protector) is available through CampMinder.', NULL, 'Activities include swimming, sailing, canoeing, kayaking, paddleboarding, waterskiing and wakeboarding. The site gives no details on lifeguards or swim tests.', NULL, NULL, 2027, 'b8c60643-83f3-5b5b-8ddc-cc033b8dce8a', 'camp-timanous-raymond', ST_GeogFromText('SRID=4326;POINT(-70.4685 43.9176)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.timanous.org/','https://www.timanous.org/faq.html']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Vega', NULL, 'https://campvega.com/', 'https://vega.campintouch.com/ui/forms/application/camper/App', 'info@campvega.com', '207-685-3707', '317 Echo Lake Rd.', 'Fayette', 'ME', '04349', 'Maine', 'sleepaway', ARRAY['sports','arts','performing_arts','nature']::text[], NULL, ARRAY['Culinary arts','Digital media/Camp Vega TV','Equestrian','Fine arts','Figure skating','Gymnastics, cheering & stunting','Landsports & fitness','Olympics (color war)','Outdoor adventure & mountain biking','Dance','Music','Theater','Ropes course','Sailing & watercrafts','Swimming','Tennis','Waterskiing & wakeboarding']::text[], 'girls', 7, 15, NULL, NULL, 'An overnight summer camp for girls on Echo Lake in Fayette, Maine. It runs one full session of about seven weeks, with activities including sports, arts, waterfront and horseback riding.', NULL, NULL, 18000, 18000, NULL, NULL, NULL, TRUE, NULL, NULL, 'All payments are fully refunded up to 100 days before opening day, minus non-refundable costs such as credit card fees or chaperoned airline bookings. Within 100 days of opening or during camp, refunds exclude those costs and the $4,000 deposit, unless the reason is illness or injury. Refunds during camp are pro-rated.', NULL, 'The camp is on Echo Lake. Activities include swimming, sailing and watercraft, and waterskiing and wakeboarding. The page gives no details about lifeguards or swim tests.', NULL, NULL, 2027, '0919c9f3-bfee-5f7f-818c-888753a5188c', 'camp-vega-fayette', ST_GeogFromText('SRID=4326;POINT(-70.067 44.434)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://campvega.com/girls_summer_camp/','https://campvega.com/parents/rates-dates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Walden', NULL, 'https://campwalden.com/', 'https://waldenme.campintouch.com/ui/forms/application/camper/App', 'walden@campwalden.com', '(207) 452-2901', '93 Camp Walden Drive, P.O. Box 230', 'Denmark', 'ME', '04022', 'Maine', 'sleepaway', ARRAY['sports','nature']::text[], NULL, ARRAY['wilderness trips','horseback riding','tennis','sailing','water skiing','ropes course']::text[], 'girls', 8, 15, NULL, NULL, 'A 7-week traditional overnight summer camp for girls ages 8–15 in Denmark, Maine, running since 1916. Activities include wilderness trips, horseback riding, tennis, sailing and water skiing.', NULL, NULL, 16000, 16000, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, 'eda42014-64a5-5983-8ab4-017b3d778232', 'camp-walden-denmark', ST_GeogFromText('SRID=4326;POINT(-70.8137 43.9962)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://campwalden.com/dates-rates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Wawenock', 'Camp Wawenock', 'https://campwawenock.com', 'https://campwawenock.com/enroll/', 'wawenock@campwawenock.com', '(207) 655-4657', '33 Wawenock Rd', 'Raymond', 'ME', '04071', 'Maine', 'sleepaway', ARRAY['sports','arts','performing_arts','nature']::text[], NULL, ARRAY['Creative arts','Waterfront','Performing arts','Tennis','Nature/outdoor living','Target sports','Horseback riding (optional fee)','Out-of-camp trips','Golf clinic (optional fee)','Ballet intensives (optional)','Athletic training & conditioning (optional)','Red Cross lifeguard training (optional)','Senior overnight trips (camping, rafting, rock climbing, biking, hiking, sea kayaking)']::text[], 'girls', NULL, NULL, 2, 10, 'All-girls overnight camp in Raymond, Maine. It offers a 7-week full season, two half seasons, and shorter introductory programs for younger girls (Wayseeker, 2 weeks, and Wonder Week, 1 week).', NULL, NULL, 2900, 13700, NULL, NULL, NULL, NULL, NULL, NULL, 'You can get the tuition deposit back if you cancel by February 1. Tuition is not reduced if a camper arrives late or leaves early, except for illness. In that case the family and the camp each cover half the loss.', NULL, 'Waterfront is one of the program areas. Red Cross Lifeguard Training is an optional $250 add-on for Full Season campers who are 15 or older and have passed the Red Cross prerequisites. Space is limited.', NULL, NULL, 2027, '87390484-679a-505a-992a-6ff1bb9313b7', 'camp-wawenock-raymond', ST_GeogFromText('SRID=4326;POINT(-70.4685 43.9176)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://campwawenock.com/about-us/dates-rates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Wigwam', NULL, 'https://www.campwigwam.com', 'https://www.ultracamp.com/clientlogin.aspx?campCode=CWE&idCamp=1324', 'neal@campwigwam.com', '(207) 583-2300', '57 Wigwam Pass', 'Waterford', 'ME', '04088', 'Maine', 'sleepaway', ARRAY['sports','arts','outdoor']::text[], NULL, ARRAY['Tennis','Golf','Arts','Rustic camping and trips in the White Mountain National Forest']::text[], 'boys', NULL, NULL, NULL, NULL, 'Overnight summer camp on Bear Lake in Waterford, Maine, running since 1910. For 2027 it offers a full-summer session, two half-summer sessions (the second open to campers 13 and under) and two shorter Rookie sessions for first-time campers age 11 and under.', NULL, NULL, 5200, 15800, NULL, NULL, NULL, NULL, NULL, NULL, 'A $750 deposit is due at registration. Enrollment can be cancelled without obligation before February 1. If camp is not the right fit, the camp will work with the family on a prorated tuition refund.', NULL, 'The camp sits on 40 acres on Bear Lake. The site gives no details on swimming or the waterfront.', NULL, NULL, 2027, '0bf10e6a-b296-511e-85e5-3427f5b55f1e', 'camp-wigwam-waterford', ST_GeogFromText('SRID=4326;POINT(-70.7223 44.2028)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.campwigwam.com/about','https://www.campwigwam.com/dates-rates']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Wildwood', NULL, 'https://www.campwildwood.com', 'https://www.campwildwood.com/camper-application-best-boys-summer-sleepaway-camp-bridgton-maine', 'campwildwood@campwildwood.com', '207-647-8864', NULL, 'Bridgton', 'ME', '04009', 'Maine', 'sleepaway', NULL, NULL, NULL, 'boys', NULL, NULL, NULL, NULL, 'An overnight summer camp for boys in Bridgton, Maine. It runs a seven-week full summer session and a shorter four-week session at the start of the summer.', NULL, NULL, 12600, 18100, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '075741f4-f1d5-5a8b-83be-93a202c855e1', 'camp-wildwood-bridgton', ST_GeogFromText('SRID=4326;POINT(-70.7433 44.0475)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://tools.usps.com/zip-code-lookup.htm?citybyzipcode','https://www.campwildwood.com/dates-rates']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Winnebago', NULL, 'https://www.campwinnebago.com', 'https://www.campwinnebago.com/enroll', NULL, '1-207-767-1019', '19 Echo Lake Rd', 'Fayette', 'ME', '04349', 'Maine', 'sleepaway', NULL, NULL, NULL, 'boys', 8, 15, NULL, NULL, 'A classic Maine sleepaway camp for boys ages 8 to 15 that has stayed small on purpose, with athletics, activities and wilderness trips.', NULL, NULL, 11900, 17950, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '2a3cbb64-a8f9-524a-894d-0a72395d471e', 'camp-winnebago-fayette', ST_GeogFromText('SRID=4326;POINT(-70.067 44.434)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.campwinnebago.com/dates-rates','https://www.campwinnebago.com/faqs','https://www.campwinnebago.com/welcome-to-winnebago']::text[], '2026-11-13', '2026-11-13', TRUE),
('Center Day Camp', 'Jewish Community Alliance', 'https://www.centerdaycamp.org', 'https://mainejewish.campintouch.com/ui/forms/application/camper/App', 'cdc@mainejewish.org', '(207) 772-1959', '75 Hackett Rd.', 'Windham', 'ME', '04062', 'Maine', 'day', ARRAY['general']::text[], ARRAY['sports','arts','outdoor']::text[], ARRAY['archery','athletics','boating (sailing, canoeing, kayaking, paddleboarding)','creative arts','dance','Israeli culture','martial arts','mountain biking','music','newspaper','outdoor adventure','performing arts','swim lessons']::text[], NULL, NULL, NULL, 1, 9, 'Jewish community day camp on Sebago Basin in Windham, Maine, for grades 1 to 9, founded in 1949. Two four-week sessions plus an Art Adventures week, with boating, swim lessons, sports, arts, mountain biking and Israeli culture; buses from stops around the area.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, FALSE, TRUE, NULL, NULL, NULL, TRUE, 'https://www.centerdaycamp.org/about-us', 2027, '84b10b24-833d-548c-83b7-9f6c88bf1d58', 'center-day-camp-windham', ST_GeogFromText('SRID=4326;POINT(-70.4053 43.7947)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=75+Hackett+Rd.&city=Windham&state=ME&benchmark=Public_AR_Current&format=json','https://www.centerdaycamp.org/','https://www.centerdaycamp.org/about-us','https://www.centerdaycamp.org/registration','https://www.centerdaycamp.org/s/Center-Day-Camp-Family-Handbook-2026-7rhy.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Friends School of Portland Summer Camp', 'Friends School of Portland', 'https://www.friendsschoolportland.org', 'https://www.friendsschoolportland.org/new-page-2', 'information@friendsschoolportland.org', '207-781-6321', '11 U.S. Route One', 'Cumberland Foreside', 'ME', '04110', 'Maine', 'day', ARRAY['nature','arts']::text[], ARRAY['outdoor']::text[], ARRAY['forest play','hikes','outdoor skills','stewardship','bird and plant identification','drawing','fort building','singing','sewing','plays and skits','watercolor painting','overnight camping trip (Crow Adventure Week)','Wilderness First Aid (CIT)']::text[], NULL, 4, 14, NULL, NULL, 'Nature and arts day camp at Friends School of Portland, a Quaker school in Cumberland Foreside, Maine: Chickadee (ages 4-5), Fox (6-8) and Crow (9-11) groups plus a Counselor in Training program for 12-14. Weeks run Monday to Friday, 8:30 am to 3 pm; Crow Camp is outdoors all day and ends with a camping adventure week.', NULL, NULL, 345, 585, 415, 'week', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '5f3376cf-7a90-5401-abd6-d19f7f9a684b', 'friends-school-of-portland-summer-camp-cumberland-foreside', ST_GeogFromText('SRID=4326;POINT(-70.2512 43.7871)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://www.friendsschoolportland.org/crow-camp','https://www.friendsschoolportland.org/new-page-2','https://www.friendsschoolportland.org/summercamp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Hidden Valley Camp', NULL, 'https://hiddenvalleycamp.com', 'https://hiddenvalleycamp.com/enroll', 'summer@hiddenvalleycamp.com', '(207) 342-5177', '161 Hidden Valley Rd.', 'Freedom', 'ME', '04941', 'Maine', 'sleepaway', ARRAY['arts','nature']::text[], ARRAY['outdoor','performing_arts','swimming']::text[], ARRAY['glass and ceramics','creative arts','performing arts','dance','music','horseback riding (lessons extra)','canoeing','kayaking','windsurfing','fishing','swim instruction','ropes course','mountain biking','tennis','llama treks','organic gardening','hikes and campouts','teen wilderness trips (Hidden Valley Adventures)','counselor training (AWACs)','apprenticeships']::text[], NULL, 8, 17, NULL, NULL, 'Overnight camp on 350 acres with a private lake in Freedom, Maine, for ages 8 to 14, with teen programs (adventure trips, advanced arts, counselor training, apprenticeships) for 14 to 17. Known for arts such as glass and ceramics, plus animals, riding, water sports and outdoor trips. Most campers stay one roughly four-week session; tuition is all-inclusive.', NULL, NULL, 5350, 15900, NULL, NULL, NULL, TRUE, NULL, TRUE, NULL, NULL, 'Private lake for canoeing, windsurfing, fishing and kayaking, plus a 75 by 25 foot heated pool with swim instruction at all levels. Red Cross lifeguards, buddy system, swim evaluations on opening day, life jackets while boating.', TRUE, 'https://hiddenvalleycamp.com/parents/faq', 2027, 'c1ae08fc-72f7-576e-8045-8f6a5efc447c', 'hidden-valley-camp-freedom', ST_GeogFromText('SRID=4326;POINT(-69.3476 44.494)'), FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://hiddenvalleycamp.com/about','https://hiddenvalleycamp.com/contact','https://hiddenvalleycamp.com/parents/dates-and-tuition','https://hiddenvalleycamp.com/parents/faq','https://hiddenvalleycamp.com/programs']::text[], '2026-11-13', '2026-11-13', TRUE),
('Kennebec Explorers Camp', 'Maine Maritime Museum', 'https://www.mainemaritimemuseum.org/kennebec-explorers/', 'https://maritimeme.campbrainregistration.com/?returnUrl=%252FLanding', 'camp@maritimeme.org', '(207) 443-1316', '243 Washington St', 'Bath', 'ME', '04530', 'Maine', 'day', ARRAY['nature','STEM','arts']::text[], NULL, ARRAY['Nature hikes','Beach trips','Shipyard games','Crafts','Science experiments','Field trips','Boat cruises on the Kennebec River','Guest speakers (select weeks)','Museum exploration']::text[], NULL, NULL, NULL, 2, 5, 'Five-day, mostly outdoor day camp at Maine Maritime Museum in Bath for rising grades 2 to 5, with a different theme each week. Campers explore the Kennebec Estuary through field trips, river boat cruises, games, science experiments and crafts; 9 am to 4 pm, with early drop-off and late pick-up for $40.', NULL, NULL, 310, 310, 310, 'week', TRUE, NULL, FALSE, TRUE, 'You must pay a $75 non-refundable deposit. If you cancel 14 or more days before the first day of camp, you get a full refund. Cancelling 7–13 days before gets you a 50% refund, and 6 days or less gets you a 25% refund. There are no refunds for cancelling during the week of camp, for any reason. If your camper doesn''t show up and you didn''t tell staff ahead of time, you''re charged the full tuition. Absences are not refunded pro rata.', NULL, NULL, NULL, NULL, 2026, 'b162e0f6-1044-5078-b3de-fd85810ecf71', 'kennebec-explorers-camp-bath', ST_GeogFromText('SRID=4326;POINT(-69.8472 43.9325)'), TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://www.mainemaritimemuseum.org/kennebec-explorers/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Kingsley Pines Camp', NULL, 'https://kingsleypines.com', 'https://kingsleypines.campintouch.com/ui/forms/application/camper/App', 'info@kingsleypines.com', '207-894-9030', '51 Coughlan Cove Road', 'Raymond', 'ME', '04071', 'Maine', 'sleepaway', ARRAY['general']::text[], ARRAY['sailing','arts','adventure']::text[], ARRAY['sailing','canoeing','swimming','wakeboarding','water trampoline','floating climbing tower','ceramics','photography','dance','ukulele','stained glass','zip-lining','ropes course','rock climbing','white-water rafting','fencing','Ultimate Frisbee','golf','yoga','traditional sports']::text[], 'coed', 8, 16, NULL, NULL, 'Family-owned coed overnight camp on Panther Lake in Raymond, Maine, for ages 8 to 16. Two-, three- and five-week sessions plus a one-week Explorer program for rising 3rd to 5th graders, with campers choosing their own activities: waterfront, arts, ropes and zip-lines, rafting and sports.', NULL, NULL, 2600, 11275, NULL, NULL, NULL, TRUE, NULL, TRUE, 'If you cancel before April 1, 2027, you get a full refund minus a $500 cancellation fee per child. No refunds after April 1, 2027. A $1,000 deposit is required to enroll. Installment plans are available. Siblings get 5% off for each additional child.', NULL, 'Waterfront on Panther Lake: sailing, canoeing, swimming, wakeboarding, a water trampoline and a 14-foot floating climbing tower.', TRUE, 'https://kingsleypines.com/frequently-asked-questions/', 2027, 'd2d7b94e-2298-53c3-bb16-42f12c389da1', 'kingsley-pines-camp-raymond', ST_GeogFromText('SRID=4326;POINT(-70.4685 43.9176)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://kingsleypines.com/','https://kingsleypines.com/activities/','https://kingsleypines.com/frequently-asked-questions/','https://kingsleypines.com/rates-dates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Laurel South', NULL, 'https://www.camplaurelsouth.com', 'https://www.camplaurelsouth.com/apply/', 'fun@camplaurelsouth.com', '800-327-3506', '48 Laurel Road', 'Casco', 'ME', '04015', 'Maine', 'sleepaway', ARRAY['general','sports']::text[], ARRAY['arts','adventure','swimming']::text[], ARRAY['athletics','waterfront','tennis','adventure','Inter-Arts','special areas','soccer','basketball','baseball','softball','archery','swimming','sailing','equestrian (optional, extra fee)']::text[], 'coed', NULL, NULL, 3, 10, 'Coed overnight camp on Crescent Lake in Casco, Maine, for campers who have completed grades 2 to 9, with about 200 boys and 200 girls each 3.5-week session. Individually scheduled programs in athletics, waterfront, tennis, adventure and Inter-Arts, with in-camp leagues and intercamp teams.', NULL, NULL, 10800, 10800, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, 'On 3-mile-long Crescent Lake; the camp says the lake is naturally warmed and reaches about 80 degrees during the day.', NULL, NULL, 2027, 'a539f935-1959-587d-82d8-ed7833bcb178', 'laurel-south-casco', ST_GeogFromText('SRID=4326;POINT(-70.5132 43.952)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.camplaurelsouth.com/','https://www.camplaurelsouth.com/about-camp-laurel-south/frequently-asked-questions/','https://www.camplaurelsouth.com/summer-camp-families/dates-fees/']::text[], '2026-11-13', '2026-11-13', TRUE)
